from pathlib import Path

# 1) Add career-spanning training / facilitation / speaking case study.
p = Path('projects-core.js')
s = p.read_text(encoding='utf-8')
if "id:'training-facilitation-speaking'" not in s:
    marker = "    {id:'sentinelone-partnerstruck'"
    assert marker in s, 'case-study insertion marker not found'
    entry = """    {id:'training-facilitation-speaking',company:'Cross-Company Experience',title:'Corporate Training, Facilitation & Public Speaking',role:'Enablement Leader, Facilitator & Speaker',timeline:'Career-spanning',type:'Corporate learning + facilitation + speaking',metrics:['Company-wide + SKO facilitation','Black Hat presentation','Fortune 500 L&D collaboration'],before:'Important initiatives often had strong content but still needed a facilitator who could make the message clear, relevant, interactive, and usable for the people in the room.',after:'Across companies, leadership programs, sales kickoffs, guest sessions, and conference environments, complex ideas were turned into live learning experiences built for participation, discussion, practice, and application.',objective:'Help teams turn important ideas into learning experiences people can understand, discuss, practice, and use after the session ends.',lede:'Live training has been a consistent part of my work across every organization in my career. I have facilitated internal training, presented at sales kickoffs, supported manager growth, collaborated with L&D teams, joined sessions as a guest speaker, and presented in the Black Hat conference environment.',story:'The common thread is not simply getting on a stage. The work starts with the audience and the behavior the organization needs after the session. Content is shaped around that goal, the room is designed for interaction instead of passive consumption, managers and stakeholders are brought into the experience where useful, and the session is connected to practice or reinforcement after the event. That approach has been used in company-wide presentations, sales kickoffs, manager development, cybersecurity learning, guest collaborations, and enterprise L&D environments.',why:'A strong presentation can create energy, but corporate learning only matters when people understand what to do differently afterward. Teams needed live experiences that could translate strategy, methodology, technical concepts, and leadership expectations into clear action.',how:'Designed and delivered workshops, presentations, facilitated discussions, manager-development sessions, kickoff experiences, and collaborative learning with a focus on adult learning, audience relevance, interaction, practice, and practical follow-through.',process:['Clarify the business goal and the audience','Define what people should know or do differently afterward','Turn complex material into a clear live narrative','Design participation, discussion, and practice into the session','Adapt facilitation to executives, managers, sellers, partners, or technical audiences','Use stories, scenarios, and examples to make the material usable','Build in questions, feedback, and room-level interaction','Connect the live session to reinforcement or follow-up where needed','Use audience and stakeholder feedback to improve the next delivery'],pm:['Live sessions were treated as part of a broader enablement system rather than isolated presentations.','The format changed with the audience: executive communication, manager growth, seller readiness, partner learning, technical education, and conference speaking each required a different facilitation approach.','The focus stayed on clarity, confidence, participation, and what the audience needed to do next.'],programs:['Corporate training workshops','Sales kickoffs and enablement events','Manager development and growth sessions','Guest speaking and collaborative sessions','Conference presentations including Black Hat','Enterprise and Fortune 500 L&D collaboration'],tools:['Live facilitation','Adult learning design','Workshop design','Executive storytelling','Scenario practice','Manager coaching','Interactive exercises','Presentation design'],outcomes:[['Career-spanning','Presented and facilitated across every organization in my career'],['SKO','Designed, ran, and presented at sales kickoffs'],['Black Hat','Presented in a major cybersecurity conference environment'],['Fortune 500','Worked alongside enterprise L&D teams and learning programs'],['Invited','Guest speaker and collaborator']],note:'Business need → audience → learning objective → live experience → practice → discussion → reinforcement → application.'},\n"""
    s = s.replace(marker, entry + marker, 1)
    p.write_text(s, encoding='utf-8')

# 2) Add a sellable corporate training / facilitation service.
p = Path('work-with-me.html')
s = p.read_text(encoding='utf-8')
if 'Corporate training, facilitation & speaking' not in s:
    existing = '<article class="service-card"><span class="num">06</span><small>Enablement platforms & learning experiences</small>'
    assert existing in s, 'service-card insertion marker not found'
    s = s.replace(existing, '<article class="service-card"><span class="num">07</span><small>Enablement platforms & learning experiences</small>', 1)
    new_card = '<article class="service-card"><span class="num">06</span><small>Corporate training, facilitation & speaking</small><h3>Make the room worth people&#39;s time.</h3><p>We design and deliver live learning experiences that make complex ideas clear, interactive, and usable after the session ends.</p><ul><li>Corporate workshops and team training</li><li>Manager development and leadership facilitation</li><li>SKOs, offsites, kickoffs, and enablement events</li><li>Guest speaking, panels, conference sessions, and collaboration</li></ul></article>\n'
    new_marker = '<article class="service-card"><span class="num">07</span><small>Enablement platforms & learning experiences</small>'
    s = s.replace(new_marker, new_card + new_marker, 1)
    s = s.replace('Work with EZ Enablement on sales enablement, partner training, AI adoption, learning design, GTM systems, academies, certification, coaching, and enablement platforms.', 'Work with EZ Enablement on corporate training, facilitation, sales enablement, partner training, manager development, AI adoption, learning design, GTM systems, academies, certification, and enablement platforms.', 1)
    s = s.replace('"Training","Sales Enablement"', '"Training","Corporate Training","Facilitation","Public Speaking","Manager Development","Sales Enablement"', 1)
    p.write_text(s, encoding='utf-8')

# 3) Surface the offer on the homepage and structured data.
p = Path('index.html')
s = p.read_text(encoding='utf-8')
if '<strong>Corporate Training & Facilitation</strong>' not in s:
    old = '<a class="home-offer" href="work-with-me.html#offers"><small>06 / BUILD THE EXPERIENCE</small><strong>Enablement Platforms & Learning Experiences</strong><span>Portals, academies, resource hubs, interactive tools, simulations, and digital learning experiences.</span></a>'
    assert old in s, 'homepage offer marker not found'
    replacement = '<a class="home-offer" href="work-with-me.html#offers"><small>06 / LEAD THE ROOM</small><strong>Corporate Training & Facilitation</strong><span>Workshops, manager development, SKOs, offsites, guest speaking, and live learning experiences.</span></a><a class="home-offer" href="work-with-me.html#offers"><small>07 / BUILD THE EXPERIENCE</small><strong>Enablement Platforms & Learning Experiences</strong><span>Portals, academies, resource hubs, interactive tools, simulations, and digital learning experiences.</span></a>'
    s = s.replace(old, replacement, 1)
    s = s.replace('"Training","Sales Enablement"', '"Training","Corporate Training","Facilitation","Public Speaking","Manager Development","Sales Enablement"', 1)
    p.write_text(s, encoding='utf-8')
